content:
:root {
  color-scheme: dark;
  --bg: #080d13;
  --panel: #0e1620;
  --panel-2: #0b121a;
  --panel-3: #151f2c;
  --line: #263445;
  --line-strong: #34495f;
  --text: #e6edf3;
  --muted: #8fa1b7;
  --accent: #f87171;
  --baseline: #fbbf24;
  --history: #60a5fa;
  --shocked: #c084fc;
  --good: #34d399;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
}

body {
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--text);
}

a {
  color: var(--history);
}

.app-shell {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr) minmax(360px, 430px);
  min-height: calc(100vh - 1.5rem);
  margin: 0.75rem;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.45);
}

.panel {
  min-width: 0;
  padding: 18px 18px 24px;
  overflow-y: auto;
  max-height: calc(100vh - 2.5rem);
}

.panel-left {
  background: linear-gradient(180deg, #0e1620 0%, #0a1018 100%);
  border-right: 1px solid var(--line);
}

.panel-center {
  display: flex;
  flex-direction: column;
  background: var(--panel);
  border-right: 1px solid var(--line);
}

.panel-right {
  display: flex;
  flex-direction: column;
  background: var(--panel-2);
}

.app-title {
  margin: 0 0 6px;
  font-size: 1.35rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.app-subtitle {
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.45;
  margin-bottom: 20px;
}

.section-title {
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #c7d3e1;
  margin: 0 0 14px;
}

.muted {
  color: var(--muted);
}

.small-note {
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.4;
  margin: 2px 0 8px;
}

.form-group {
  margin-bottom: 14px;
}

.control-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: #c7d3e1;
  margin-bottom: 6px;
}

.form-control,
.form-select {
  background-color: var(--panel-3) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-strong) !important;
  border-radius: 8px;
}

.form-control::placeholder {
  color: #6f8299;
}

.form-control:focus,
.form-select:focus {
  background-color: var(--panel-3) !important;
  color: var(--text) !important;
  border-color: var(--history) !important;
  box-shadow: 0 0 0 0.2rem rgba(96, 165, 250, 0.18) !important;
}

.form-select option {
  background: var(--panel-3);
  color: var(--text);
}

.form-check-input {
  background-color: var(--panel-3);
  border-color: var(--line-strong);
}

.form-check-input:checked {
  background-color: var(--history);
  border-color: var(--history);
}

.form-check-label {
  color: var(--text);
}

.btn-secondary {
  background-color: var(--panel-3) !important;
  border-color: var(--line-strong) !important;
  color: var(--text) !important;
}

.btn-secondary:hover,
.btn-secondary:focus {
  background-color: #223247 !important;
  border-color: #48627f !important;
  color: #ffffff !important;
}

.input-error {
  color: #fca5a5;
  font-size: 0.72rem;
  line-height: 1.35;
  margin: -6px 0 8px;
}

.button-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 7px;
  margin: 14px 0 0;
}

.button-row .btn {
  width: 100%;
  font-size: 0.78rem;
}

.center-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.center-head .section-title {
  margin-bottom: 0;
}

.center-head .shiny-input-container {
  min-width: 250px;
  margin-bottom: 0;
}

.center-head .control-label {
  display: none;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 8px 0 14px;
}

.metric-card {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--panel-3);
  padding: 10px 12px;
}

.metric-label {
  font-size: 0.67rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.metric-value {
  font-size: 1.15rem;
  font-weight: 800;
  line-height: 1.35;
  font-variant-numeric: tabular-nums;
}

.metric-value.baseline {
  color: var(--baseline);
}

.metric-value.shocked {
  color: var(--accent);
}

.metric-value.delta {
  color: var(--history);
}

.metric-sub {
  color: var(--muted);
  font-size: 0.67rem;
  line-height: 1.35;
}

.shiny-plot-output {
  max-width: 100%;
}

.method-note {
  font-size: 0.72rem;
  line-height: 1.5;
  color: var(--muted);
  border-top: 1px solid var(--line);
  padding-top: 10px;
  margin-top: 12px;
}

.bars-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  flex: 1 1 auto;
  min-height: 0;
  align-items: stretch;
}

.contrib-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel-3);
  padding: 10px;
}

.contrib-head {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 8px;
}

.total-value {
  color: var(--accent);
  font-size: 0.95rem;
  font-weight: 800;
}

.total-sub {
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 600;
}

.bar-area {
  display: flex;
  flex: 1 1 auto;
  justify-content: center;
  min-height: 240px;
  padding: 4px 0 8px;
}

.stack-bar {
  position: relative;
  width: clamp(80px, 68%, 130px);
  height: 100%;
  min-height: 240px;
  background: #070d13;
  border-radius: 7px;
  overflow: visible;
  border: 1px solid var(--line-strong);
}

.bar-segment {
  position: absolute;
  left: 0;
  width: 100%;
  cursor: help;
  outline: none;
  border-top: 1px solid rgba(255, 255, 255, 0.3);
}

.bar-segment:focus-visible {
  box-shadow: inset 0 0 0 2px #ffffff;
}

.bar-segment::after {
  content: attr(data-tooltip);
  position: absolute;
  left: 110%;
  top: 50%;
  transform: translateY(-50%);
  min-width: 190px;
  max-width: 250px;
  white-space: normal;
  background: #1f2937;
  color: #f8fafc;
  border: 1px solid #475569;
  padding: 8px 10px;
  border-radius: 7px;
  font-size: 0.7rem;
  line-height: 1.35;
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease;
  z-index: 30;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.55);
}

.bar-segment:hover::after,
.bar-segment:focus::after {
  opacity: 1;
}

.country-card .bar-segment::after {
  left: auto;
  right: 110%;
}

.zero-line {
  position: absolute;
  left: -5px;
  right: -5px;
  border-top: 2px solid #cbd5e1;
  z-index: 5;
  pointer-events: none;
}

.empty-bar {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  justify-content: center;
  min-height: 180px;
  text-align: center;
  color: var(--muted);
  font-size: 0.76rem;
  background: var(--panel-2);
  border: 1px dashed var(--line);
  border-radius: 8px;
}

.legend-scroll {
  max-height: min(22vh, 220px);
  overflow-y: auto;
  border-top: 1px solid var(--line);
  padding-top: 6px;
  margin-top: 4px;
}

.legend-row {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
  padding: 2px 0;
  font-size: 0.66rem;
  line-height: 1.25;
}

.swatch {
  width: 9px;
  height: 9px;
  border-radius: 2px;
  display: inline-block;
}

.legend-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #b9c7d8;
}

.legend-value {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.legend-value.pos {
  color: #fca5a5;
}

.legend-value.neg {
  color: #93c5fd;
}

.legend-share {
  display: none;
}

::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

::-webkit-scrollbar-track {
  background: #0a1018;
}

::-webkit-scrollbar-thumb {
  background: #33475e;
  border-radius: 8px;
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 260px minmax(0, 1fr) minmax(340px, 390px);
  }

  .metrics-grid {
    gap: 8px;
  }

  .metric-card {
    padding: 9px 10px;
  }

  .metric-value {
    font-size: 1.02rem;
  }
}

@media (max-width: 980px) {
  .app-shell {
    grid-template-columns: 1fr;
    margin: 0;
    border-radius: 0;
  }

  .panel {
    max-height: none;
    border-right: none;
    border-bottom: 1px solid var(--line);
  }

  .bars-grid {
    min-height: 420px;
  }
}

@media (max-width: 620px) {
  .metrics-grid,
  .bars-grid {
    grid-template-columns: 1fr;
  }

  .stack-bar {
    min-height: 220px;
  }
}
